def api_call(endpoint, params=None):
    url = f"{BASE_URL}/api/{endpoint}"
    if params:
        url += "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": f"Bearer {BOT_TOKEN}"})
    with urllib.request.urlopen(req) as resp:
        return json.loads(resp.read())

# Get all public channels
channels = []
cursor = None
while True:
    params = {"types": "public_channel", "limit": 200}
    if cursor:
        params["cursor"] = cursor
    data = api_call("conversations.list", params)
    if not data.get("ok"):
        break
    for ch in data.get("channels", []):
        if not ch.get("is_archived"):
            channels.append({"id": ch["id"], "name": ch["name"]})
    cursor = data.get("response_metadata", {}).get("next_cursor")
    if not cursor:
        break

print(f"Found {len(channels)} non-archived public channels")

user_reactions = {}
user_names = {}

def get_user_info(user_id):
    if user_id in user_names:
        return user_names[user_id]
    try:
        data = api_call("users.info", {"user": user_id})
        if data.get("ok"):
            u = data["user"]
            name = u.get("real_name") or u.get("name") or user_id
            user_names[user_id] = name
            return name
    except:
        pass
    user_names[user_id] = user_id
    return user_id

total_messages = 0
total_with_reactions = 0

for ch in channels:
    ch_id = ch["id"]
    ch_name = ch["name"]

    try:
        api_call("conversations.join", {"channel": ch_id})
    except:
        pass

    messages = []
    cursor = None
    while True:
        params = {"channel": ch_id, "limit": 200}
        if cursor:
            params["cursor"] = cursor
        try:
            data = api_call("conversations.history", params)
        except Exception as e:
            print(f"  Error in #{ch_name}: {e}")
            break
        if not data.get("ok"):
            print(f"  Error in #{ch_name}: {data.get('error', 'unknown')}")
            break
        msgs = data.get("messages", [])
        messages.extend(msgs)
        cursor = data.get("response_metadata", {}).get("next_cursor")
        if not cursor:
            break

    if messages:
        print(f"#{ch_name}: {len(messages)} messages")

    for msg in messages:
        if msg.get("subtype"):
            continue
        user_id = msg.get("user")
        if not user_id:
            continue
        msg_ts = msg.get("ts")
        text = msg.get("text", "")[:300]
        reactions = msg.get("reactions", [])

        if reactions:
            total_with_reactions += 1

        total_reaction_count = 0
        reaction_details = []
        for r in reactions:
            count = r.get("count", 0)
            # Subtract self-reactions (user reacted to their own message)
            reacting_users = r.get("users", [])
            self_reacted = user_id in reacting_users
            adjusted_count = count - (1 if self_reacted else 0)
            total_reaction_count += max(0, adjusted_count)
            if adjusted_count > 0:
                reaction_details.append(f"{r.get('name')}x{adjusted_count}")

        if total_reaction_count > 0:
            if user_id not in user_reactions:
                user_reactions[user_id] = {"total_reactions": 0, "messages": []}
            user_reactions[user_id]["total_reactions"] += total_reaction_count
            user_reactions[user_id]["messages"].append({
                "channel": ch_name,
                "ts": msg_ts,
                "text": text,
                "reactions": total_reaction_count,
                "details": ", ".join(reaction_details[:5]),
                "timestamp": datetime.fromtimestamp(float(msg_ts), tz=timezone.utc).isoformat()
            })

    total_messages += len(messages)

print(f"\n=== SUMMARY ===")
print(f"Total messages scanned: {total_messages}")
print(f"Messages with reactions: {total_with_reactions}")
print(f"Unique users with reactions: {len(user_reactions)}")

ranking = sorted(user_reactions.items(), key=lambda x: x[1]["total_reactions"], reverse=True)

print(f"\n=== REACTION LEADERBOARD ===")
for rank, (user_id, data) in enumerate(ranking[:10], 1):
    name = get_user_info(user_id)
    print(f"\n#{rank}: {name} ({user_id}) -- {data['total_reactions']} reactions")
    for m in data["messages"][:5]:
        print(f"   #{m['channel']} [{m['timestamp']}]: {m['text'][:100]}... [{m['details']}]")

result = {
    "ranking": [
        {
            "rank": i+1,
            "user_id": uid,
            "name": get_user_info(uid),
            "total_reactions": d["total_reactions"],
            "messages": d["messages"]
        }
        for i, (uid, d) in enumerate(ranking[:10])
    ]
}
with open("/tmp/slack_leaderboard.json", "w") as f:
    json.dump(result, f, indent=2)

print("\nFull results saved to /tmp/slack_leaderboard.json")
